"use client";
/* Ball, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Ball(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("ball"); }, []);
  return React.createElement("piix-pal", { "pal": "ball", ...piixAttrs(props) });
}

export default Ball;
